# rebuild demos with explicit seed/edges

def blank(h,w,v): return [[v]*w for _ in range(h)]
def validate_h(h,w,bg,wall,left,right,seeds,refill):
    a=blank(h,w,bg)
    for r in left:a[r][0]=wall
    for r in right:a[r][w-1]=wall
    for r,c,col in seeds:a[r][c]=col
    e=blank(h,w,bg)
    for r in left:e[r][0]=wall
    for r in right:e[r][w-1]=wall
    for r,c,col in seeds:
        e[r][c]=4
        # Ray toward edge indicated in that seed's wall block.
        if r in left:
            for x in range(1,c):e[r][x]=col
        elif r in right:
            for x in range(c+1,w-1):e[r][x]=col
    # transfer each occupied row-pattern to matched opposite side
    if refill:
        for r,c,col in seeds:
            if r in left:
                idx=left.index(r)
                if idx<len(right):
                    for x in range(1,w-1): e[right[idx]][x]=col
            elif r in right:
                idx=right.index(r)
                if idx<len(left):
                    for x in range(1,w-1): e[left[idx]][x]=col
    return a,e
